14: func request(taskType string) taskplan.Request {
15: 	text := "---\r\ntype: " + taskType + "\r\ntitle: Existing contract\r\ndone_when: checked\r\n"
16: 	if taskType == "review" {
17: 		text += "review_of: t3\r\n"
18: 	}
19: 	text += "---\r\nUser words: \"Keep this exact.\"\r\n"
20: 	r := taskplan.Request{Brief: taskplan.Select("brief", "brief.md", []byte(text)),
21: 		Execution: taskplan.Execution{Scope: "repo", Base: "main", Target: "main"},
22: 		Launch:    taskplan.Launch{ProfileName: "deep", Profile: config.Profile{Kind: "pi", Model: "configured-model", Args: []string{"--name", "worker"}}, Args: []string{"--model", "configured-model"}, ModelKnown: true, ConfiguredModel: "configured-model"},
23: 		Review:    "none", Delivery: "local", Autonomy: config.Autonomy{Review: "ask", Merge: "ask"}, ProseLanguage: "vi",
24: 		Paths: taskplan.Paths{Scratch: "/managed/scratch/shop/{task}", Output: "/managed/projects/shop/tasks/{task}"}}
25: 	if taskType == "review" {
26: 		r.ReviewOf = 3
27: 	}
28: 	return r
29: }
